519	export function defineTool<S extends z.ZodTypeAny>(t: { name: string; description: string; parameters: S; execute(args: z.infer<S>): Promise<unknown> }): Tool
520	
521	export async function completeJson<T>(o: { client: ModelClient; role: Role; name: string; system: string; user: string | ContentPart[]; output: z.ZodType<T> }): Promise<T>
522	export async function runAgent<T>(o: { client: ModelClient; role: Role; name: string; system: string; user: string; tools: Tool[]; output: z.ZodType<T>; maxSteps?: number }): Promise<{ output: T; steps: number }>
523	export class AgentStepLimitError extends Error {}
524	export class ModelOutputError extends Error {}
525	
526	export async function initTracing(env: Env, workflowName: string): Promise<void>
527	export async function shutdownTracing(): Promise<void>
528	export function traced<A extends unknown[], R>(kind: 'WORKFLOW' | 'CHAIN' | 'AGENT' | 'TOOL' | 'GUARDRAIL', name: string, fn: (...a: A) => Promise<R>): (...a: A) => Promise<R>
529	export async function guard(name: string, check: () => Promise<{ pass: boolean; reasons: string[] }>): Promise<{ pass: boolean; reasons: string[] }>
