121	    const sha = fields[i]!.trim();
122	    const body = fields[i + 1]!;
123	    if (SHA_RE.test(sha)) commits.push({ sha, body });
124	  }
125	
126	  const kept = commits.slice(0, maxCommits);
127	  const droppedCount = Math.max(0, commits.length - maxCommits);
128	
129	  const diffs: Record<string, string> = {};
130	  for (const { sha, body } of kept) {
