136	/** A long-lived `git cat-file --batch` process: write an object id, read its full content back. */
137	export class ObjectBatchReader {
138	  private readonly proc: ChildProcessWithoutNullStreams;
139	  private readonly pending: Array<{ resolve: (buf: Buffer | null) => void; reject: (err: Error) => void }> = [];
140	  private buffer: Buffer = Buffer.alloc(0);
141	  private closed = false;
142	
143	  constructor(repoDir: string) {
144	    this.proc = spawn('git', ['cat-file', '--batch'], {
145	      cwd: repoDir,
146	      // Promisor objects outside a partial clone's filter would otherwise be fetched one at a
147	      // time, each a network round trip; this makes cat-file report them missing instead so the
148	      // caller can decide whether to fetch, in one explicit step.
149	      env: { ...process.env, GIT_NO_LAZY_FETCH: '1' },
150	    });
151	    this.proc.stdout.on('data', (chunk: Buffer) => {
152	      this.buffer = this.buffer.length === 0 ? chunk : Buffer.concat([this.buffer, chunk]);
153	      this.drain();
154	    });
155	    const failAll = (err: Error) => {
156	      while (this.pending.length > 0) this.pending.shift()!.reject(err);
157	    };
158	    this.proc.on('error', failAll);
159	    this.proc.stdin.on('error', failAll);
160	  }
161	
162	  private drain(): void {
163	    while (this.pending.length > 0) {
164	      const nl = this.buffer.indexOf(0x0a);
165	      if (nl === -1) return;
166	      const header = this.buffer.subarray(0, nl).toString('utf8');
167	      if (header.endsWith(' missing')) {
168	        this.buffer = this.buffer.subarray(nl + 1);
169	        this.pending.shift()!.resolve(null);
170	        continue;
171	      }
172	      const m = /^[0-9a-f]{40,64} \S+ (\d+)$/.exec(header);
173	      if (!m) {
174	        this.buffer = this.buffer.subarray(nl + 1);
175	        continue;
176	      }
177	      const size = Number(m[1]);
178	      const need = nl + 1 + size + 1;
179	      if (this.buffer.length < need) return;
180	      const data = Buffer.from(this.buffer.subarray(nl + 1, nl + 1 + size));
181	      this.buffer = this.buffer.subarray(need);
