186	  /** Resolves with the object's content, or `null` when the object is missing locally. */
187	  read(oid: string): Promise<Buffer | null> {
188	    if (this.closed) return Promise.resolve(null);
189	    return new Promise((resolvePromise, reject) => {
190	      this.pending.push({ resolve: resolvePromise, reject });
191	      this.proc.stdin.write(`${oid}\n`);
192	    });
193	  }
194	
195	  close(): void {
196	    if (this.closed) return;
197	    this.closed = true;
198	    this.proc.stdin.end();
199	    this.proc.kill();
200	  }
201	}
