206	  if (first !== null) return first;
207	  await git(repoDir, ['fetch', 'origin', oid]);
208	  const second = await reader.read(oid);
209	  if (second === null) throw new Error(`object ${oid} is unavailable even after fetching it`);
210	  return second;
211	}
