        { sessionId: 'shared', createdAt: '2026-10-10T00:00:00Z' },
        { sessionId: 'shared', createdAt: '2026-10-11T00:00:00Z' },
      ],
      '2026-10-01T00:00:00Z',
      '2026-10-20T00:00:00Z',
      12,
